"use client";

import { cn } from "@/lib/utils";

interface SegmentedControlProps {
    options: { label: string; value: string }[];
    value: string;
    onChange: (value: string) => void;
    label?: string;
    className?: string;
}

export default function SegmentedControl({ options, value, onChange, label, className }: SegmentedControlProps) {
    return (
        <div className={cn("space-y-1.5", className)}>
            {label && (
                <label className="text-[12px] font-bold text-slate-700 dark:text-slate-200 tracking-tight">
                    {label}
                </label>
            )}
            <div className="flex p-1 bg-slate-100 dark:bg-slate-800/80 rounded-xl border border-slate-200 dark:border-slate-700 self-start">
                {options.map((option) => {
                    const isActive = value === option.value;
                    return (
                        <button
                            key={option.value}
                            type="button"
                            onClick={() => onChange(option.value)}
                            className={cn(
                                "px-4 py-2 text-[11px] font-black uppercase tracking-wider rounded-lg transition-all duration-200",
                                isActive
                                    ? "bg-white dark:bg-slate-700 text-primary shadow-sm ring-1 ring-slate-200 dark:ring-slate-600 scale-100"
                                    : "text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 scale-95"
                            )}
                        >
                            {option.label}
                        </button>
                    );
                })}
            </div>
        </div>
    );
}
